package merge

import (
	"reflect"
	"testing"
)

type gsrWitnessLister struct {
	items []string
}

func (l gsrWitnessLister) List() []string {
	return l.items
}

func TestGSRWitness(t *testing.T) {
	a := gsrWitnessLister{items: []string{"a"}}
	b := gsrWitnessLister{items: []string{"a"}}

	got := Merge(a, b)
	want := []string{"a"}

	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Merge(a, b) = %q, want %q", got, want)
	}
}

