package saver

import (
	"context"
	"testing"
)

type gsrWitnessFakeStore struct {
	calls int
}

func (f *gsrWitnessFakeStore) Put(ctx context.Context, key, value string) error {
	f.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessFakeStore{}
	_ = Save(ctx, store, "id1", "val1", "val2")

	if store.calls > 1 {
		t.Fatalf("Save with cancelled context made %d Put calls, want at most 1", store.calls)
	}
}

