package upload

import (
	"errors"
	"testing"
)

type gsrWitnessFailingWriter struct {
	flushed bool
}

func (w *gsrWitnessFailingWriter) Write(part string) error {
	return errors.New("write failed")
}

func (w *gsrWitnessFailingWriter) Flush() error {
	w.flushed = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessFailingWriter{}
	_ = Upload(w, []string{"part1"})
	if w.flushed {
		t.Fatalf("Upload() flushed after a failed Write; want no Flush")
	}
}

